21	// The outline variant's `disabled:` look, re-expressed for `aria-disabled` —
22	// the re-bake button stays a real, focusable element while it's locked, so
23	// keyboard and screen-reader users don't lose their place when the fetch
24	// button appears beside it. See MarketingButton's `outline` variant.
25	//
26	// The hover override earns its place: a natively disabled button is excluded
27	// from `:hover` matching, but an `aria-disabled` one is still live, so the
28	// variant's `hover:bg-muted` would light up a button that does nothing.
29	const REBAKE_LOCKED_LOOK = cn(
30	  "aria-disabled:bg-transparent aria-disabled:opacity-40",
31	  "aria-disabled:cursor-not-allowed aria-disabled:hover:bg-transparent"
32	);
33	
34	const IDLE_REBAKE_LABEL = "Re-bake this page";
35	const REBAKE_LABELS = [IDLE_REBAKE_LABEL, "Re-baking…"];
36	const FETCH_LABELS = ["Fetch what’s actually cached", "Fetching…"];
37	
38	/**
39	 * Renders `value` stacked on top of every string it could have been, so the
40	 * cell is always as tall and as wide as its worst case. Reserving by hand
41	 * means a magic number per breakpoint that a copy edit silently invalidates;
42	 * this reserves the real thing, at whatever width the reader happens to be.
43	 *
44	 * The ghosts are `visibility: hidden`, so they take space but leave the tab
45	 * order, the selection, and — with `aria-hidden` — the announcement alone.
46	 */
47	function StableSlot({
48	  className,
49	  value,
50	  variants,
51	}: {
52	  className?: string;
53	  value: string;
54	  variants: readonly string[];
55	}) {
56	  return (
57	    <span className={cn("grid", className)}>
58	      {variants.map((variant) => (
59	        <span
60	          aria-hidden="true"
61	          className="invisible [grid-area:1/1]"
62	          key={variant}
63	        >
