77	/**
78	 * Expiring a tag and refilling it are separate events, so they get separate
79	 * buttons — and the button you can't press is doing as much teaching as the
80	 * one you can.
81	 *
82	 * Every slot in here is sized for its tallest and widest state, because a
83	 * demo about cache timing is unreadable if the thing you are watching hops
84	 * down the page as it changes.
85	 */
86	export function RebakePanel({ currentId }: RebakePanelProps) {
87	  const router = useRouter();
88	  const [state, dispatch] = useReducer(rebakeReducer, INITIAL_REBAKE_STATE);
89	  const [isRebaking, startRebake] = useTransition();
90	  const [isFetching, startFetch] = useTransition();
91	  const [rebakeFailed, setRebakeFailed] = useState(false);
92	
93	  const rebakeLocked = !canRebake(state) || isRebaking;
94	  const fetchable = canFetch(state);
95	
96	  const handleRebake = useCallback(() => {
97	    // Guards the same lock the button's `aria-disabled` shows, since that
98	    // attribute doesn't stop clicks the way the native one does.
99	    if (rebakeLocked) {
100	      return;
101	    }
102	    setRebakeFailed(false);
103	    startRebake(async () => {
104	      try {
105	        const { rebakedAt } = await rebakeShell();
106	        dispatch({ at: rebakedAt, type: "expired" });
107	      } catch {
108	        // The tag may well have been expired before the response died, so the
109	        // copy promises nothing about what happened — it just says so.
110	        setRebakeFailed(true);
111	      }
112	    });
113	  }, [rebakeLocked]);
114	
115	  const handleFetch = useCallback(() => {
116	    startFetch(() => {
117	      // Captured before the refresh lands, while the private render is still
118	      // the thing on screen. Both updates sit in the same transition, so the
119	      // panel keeps showing the expired state until the new bake arrives.
120	      dispatch({ privateId: currentId, type: "refetched" });
121	      router.refresh();
122	    });
123	  }, [currentId, router]);
124	
125	  const { caption, detail, label } = readout(state, currentId);
126	  const rebakeLabel = isRebaking ? REBAKE_LABELS[1] : REBAKE_LABELS[0];
127	  const fetchLabel = isFetching ? FETCH_LABELS[1] : FETCH_LABELS[0];
128	  const captionText = rebakeFailed ? REBAKE_FAILED_CAPTION : caption;
129	
