async (page) => {
  const grab = async (name) => {
    await page.locator('#demo-02 figure').screenshot({ path: `./flow-${name}.png` });
  };
  const caption = async () => {
    const t = await page.locator('#demo-02 figure p[aria-live]').innerText();
    return t.trim().slice(0, 70);
  };
  await page.goto('http://localhost:3001/', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.locator('#demo-02').scrollIntoViewIfNeeded({ timeout: 30000 });
  await page.waitForTimeout(600);

  const out = {};
  out.arrive = await caption();
  await grab('1-simple-idle');

  // 1. Simple fused press
  await page.getByRole('button', { name: 'Re-bake this page' }).click();
  await page.waitForTimeout(2500);
  out.afterFusedPress = await caption();
  await grab('2-simple-cycled');

  // 2. Toggle on -> machinery
  await page.locator('#rebake-slow-motion').click();
  await page.waitForTimeout(400);
  out.machineryIdle = await caption();
  await grab('3-machinery-idle');

  // 3. Machinery press -> expired
  await page.getByRole('button', { name: 'Re-bake this page' }).click();
  await page.waitForTimeout(1800);
  out.expired = await caption();
  out.fetchVisible = await page.getByRole('button', { name: 'Fetch what’s actually cached' }).isVisible();
  await grab('4-machinery-expired');

  // 4. THE EDGE CASE: toggle off mid-gap -> settle
  await page.locator('#rebake-slow-motion').click();
  await page.waitForTimeout(2500);
  out.settled = await caption();
  out.fetchGoneAfterSettle = (await page.getByRole('button', { name: /Fetch/ }).count()) === 0;
  await grab('5-settled-simple');

  // 5. Full machinery cycle for completeness
  await page.locator('#rebake-slow-motion').click();
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: 'Re-bake this page' }).click();
  await page.waitForTimeout(1800);
  await page.getByRole('button', { name: 'Fetch what’s actually cached' }).click();
  await page.waitForTimeout(2500);
  out.revealed = await caption();
  await grab('6-machinery-revealed');

  return out;
}

