/* JetBrains Mono (loaded via Google Fonts in marketing layout) for the
   meta-layer voice. The design system sets --font-mono to Geist Mono for
   app-wide consistency; marketing uses a dedicated editorial face. This
   override is scoped to the .font-switzer wrapper so it only affects the
   marketing route tree. */
.font-switzer .font-mono,
.font-switzer.font-mono {
  font-family:
    "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas,
    monospace;
}

/* ── Entrance choreography ──────────────────────────────────────────────
   One movement, played two ways: the hero plays it on a clock, the sections
   play it against their own position in the viewport. Neither depends on
   JavaScript, so a failed hydration can never leave a section invisible. */
@keyframes ht-rise {
  from {
    opacity: 0;
    transform: translateY(0.75rem);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* The hero's load sequence — the thesis arrives one line at a time. Timed
   animations are supported everywhere, so this runs for every visitor; each
   element sets its own offset with --ht-delay. */
@media (prefers-reduced-motion: no-preference) {
  .ht-enter {
    animation: ht-rise 700ms cubic-bezier(0.16, 1, 0.3, 1) both;
    animation-delay: var(--ht-delay, 0ms);
  }
}

/* The same movement, scrubbed by scroll position instead. Wrapped in
   @supports on purpose: a browser without scroll-driven animations skips the
   whole rule and renders the content in place, so the fallback is the plain
   page rather than an empty one.

   This is also why the page root uses `overflow-x: clip` and not
   `overflow: hidden` — `hidden` makes the root a scroll container, and
   view() would then resolve against a box that never scrolls, leaving every
   revealed element stuck at 0% forever. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .ht-reveal {
      animation: ht-rise linear both;
      animation-timeline: view();
      animation-range: entry 5% cover 18%;
    }
  }
}

/* Marketing keyframes */
@keyframes rerender {
  0% {
    border-color: var(--color-hastoggle-orange);
  }
  40% {
    border-color: var(--color-hastoggle-orange);
  }
}

@keyframes highlight {
  0% {
    background: var(--color-hastoggle-orange);
    color: white;
  }
  40% {
    background: var(--color-hastoggle-orange);
    color: white;
  }
}

@keyframes highlightFadeIn {
  from {
    background-color: transparent;
  }
  to {
    background-color: #808080;
  }
}

@keyframes shimmer {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

@keyframes move-x {
  0% {
    transform: translateX(var(--move-x-from));
  }
  100% {
    transform: translateX(var(--move-x-to));
  }
}

/* Mirror demo — diff flash on toggle. The differing segments of the agent
   response wear this class for ~600ms after a toggle. The animation runs on
   mount, which is when each differing span enters the DOM (its React key
   changes on every toggle so it remounts; shared spans keep stable keys and
   are unaffected). prefers-reduced-motion suppresses the animation entirely
   so the swap is instantaneous. */
@keyframes mirror-flash {
  from {
    background-color: rgb(245 158 11 / 0.15);
  }
  to {
    background-color: transparent;
  }
}

.mirror-flash {
  border-radius: 0.1875rem;
  animation: mirror-flash 600ms ease-out 1;
}

@media (prefers-reduced-motion: reduce) {
  .mirror-flash {
    animation: none;
  }
}

.highlighted-line {
  padding: 2px 8px 2px 0;
  border-radius: 12px;
  animation: highlightFadeIn 0.2s ease-in-out forwards;
}

/* OG demo — image-viewer checkerboard, so a generated PNG reads as a file,
   not a styled div. */
.og-checker {
  --checker: rgb(0 0 0 / 0.055);
  background-image: conic-gradient(
    var(--checker) 25%,
    transparent 0 50%,
    var(--checker) 0 75%,
    transparent 0
  );
  background-size: 16px 16px;
}

.dark .og-checker {
  --checker: rgb(255 255 255 / 0.07);
}

/* Shiki code syntax highlighting styles */
.shiki {
  color: var(--shiki-light);
  background-color: var(--shiki-light-bg);
  @apply border-border;
}

.shiki span {
  color: var(--shiki-light);
}

.dark .shiki {
  color: var(--shiki-dark);
  background-color: var(--shiki-dark-bg);
}

.dark .shiki span {
  color: var(--shiki-dark);
}

.shiki code {
  display: grid;
  font-size: 13px;
  counter-reset: line;
}

.shiki .line:before {
  content: counter(line);
  counter-increment: line;

  @apply inline-block w-4 mr-8 text-muted-foreground text-right;
}

.shiki[title]:before {
  content: attr(title);
  @apply inline-block text-muted-foreground text-right mb-6 text-sm;
}

