async (page) => {
  const panel = () => page.locator('#demo-02 figure');
  const gauge = () => page.locator('#demo-02 figure figcaption span').first();
  await page.goto('http://localhost:3001/', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.locator('#demo-02').scrollIntoViewIfNeeded({ timeout: 30000 });
  await page.waitForTimeout(600);

  const out = {};
  await panel().screenshot({ path: './ux-1-simple.png' });
  out.gaugeIdle = (await gauge().innerText()).trim();

  // Fused press: catch the working state mid-flight
  await page.getByRole('button', { name: 'Re-bake this page' }).click();
  await page.waitForTimeout(150);
  out.gaugeMidFlight = (await gauge().innerText()).trim();
  await panel().screenshot({ path: './ux-2-working.png' });
  await page.waitForTimeout(3500);
  out.gaugeAfter = (await gauge().innerText()).trim();
  await panel().screenshot({ path: './ux-3-landed.png' });

  // Split the button
  await page.locator('#rebake-slow-motion').click();
  await page.waitForTimeout(400);
  await panel().screenshot({ path: './ux-4-split.png' });
  out.step1 = (await page.getByRole('button', { name: /Expire/ }).innerText()).trim();
  out.step2 = (await page.getByRole('button', { name: /Ask for/ }).innerText()).trim();
  out.step2DisabledBeforeExpire = await page.getByRole('button', { name: /Ask for/ }).isDisabled();

  // Machinery cycle
  await page.getByRole('button', { name: /Expire/ }).click();
  await page.waitForTimeout(3000);
  out.step2EnabledAfterExpire = !(await page.getByRole('button', { name: /Ask for/ }).isDisabled());
  await panel().screenshot({ path: './ux-5-expired.png' });
  await page.getByRole('button', { name: /Ask for/ }).click();
  await page.waitForTimeout(3000);
  await panel().screenshot({ path: './ux-6-revealed.png' });

  return out;
}

