async (page) => {
  await page.goto('http://localhost:3001/', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.locator('#demo-02').scrollIntoViewIfNeeded({ timeout: 30000 });
  await page.waitForTimeout(800);
  const out = {};
  await page.locator('#demo-02 figure').screenshot({ path: './min-1-simple.png' });
  out.headerText = (await page.locator('#demo-02 figure figcaption').innerText()).replace(/\s+/g, ' ').trim();
  out.hasFooterStrip = (await page.locator('#demo-02 figure > div').count());

  await page.locator('#rebake-slow-motion').click();
  await page.waitForTimeout(400);
  await page.locator('#demo-02 figure').screenshot({ path: './min-2-split.png' });

  // full machinery run for the working/landing visuals
  await page.getByRole('button', { name: /Expire/ }).click();
  await page.waitForTimeout(250);
  await page.locator('#demo-02 figure').screenshot({ path: './min-3-working.png' });
  await page.waitForTimeout(3000);
  await page.getByRole('button', { name: /Ask for/ }).click();
  await page.waitForTimeout(3000);
  await page.locator('#demo-02 figure').screenshot({ path: './min-4-revealed.png' });

  // mobile
  await page.setViewportSize({ width: 375, height: 800 });
  await page.waitForTimeout(400);
  await page.locator('#demo-02 figure').screenshot({ path: './min-5-mobile.png' });
  await page.setViewportSize({ width: 1200, height: 800 });
  return out;
}

