import { cacheLife } from "next/cache";
import { codeToHtml } from "shiki";

async function highlight(
  code: string,
  lang: string,
  title: string
): Promise<string> {
  "use cache";
  cacheLife("max");
  return await codeToHtml(code.trim(), {
    defaultColor: false,
    lang,
    themes: { dark: "github-dark", light: "github-light" },
    transformers: [
      {
        pre(node) {
          node.properties.title = title;
        },
      },
    ],
  });
}

