async (page) => {
  const errors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error' || msg.type() === 'warning') {
      errors.push({ type: msg.type(), text: msg.text().slice(0, 600) });
    }
  });
  page.on('pageerror', (err) => errors.push({ type: 'pageerror', text: String(err).slice(0, 600) }));
  await page.goto('http://localhost:3001/', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.locator('#demo-02').scrollIntoViewIfNeeded({ timeout: 30000 });
  await page.waitForTimeout(800);
  errors.length = 0; // ignore load-time noise (known /api/og)

  // machinery on, expire, toggle off mid-gap (the settle path)
  await page.locator('#rebake-slow-motion').click();
  await page.waitForTimeout(400);
  await page.getByRole('button', { name: /Expire/ }).click();
  await page.waitForTimeout(2500);
  await page.locator('#rebake-slow-motion').click();
  await page.waitForTimeout(3000);
  const settlePath = [...errors];
  errors.length = 0;

  // plain toggle on/off with no gap
  await page.locator('#rebake-slow-motion').click();
  await page.waitForTimeout(400);
  await page.locator('#rebake-slow-motion').click();
  await page.waitForTimeout(1000);
  const plainToggle = [...errors];

  return { settlePath, plainToggle };
}

