84	    expect(canRebake(state)).toBe(true);
85	    expect(canFetch(state)).toBe(false);
86	  });
87	
88	  test("switching off mid-gap settles into the simple view, cycle complete", () => {
89	    // The panel pairs this transition with a router.refresh() — see
90	    // handleToggle — so the simple view never rests on an unanswered expiry.
91	    const state = toggle(expire(MACHINERY_SERVED));
92	    expect(state).toEqual({
93	      hasCompletedCycle: true,
94	      mode: "simple",
95	      phase: "served",
96	    });
97	  });
98	
99	  test("switching off after the reveal drops the comparison, which belongs to the machinery view", () => {
100	    const state = toggle(refetch(expire(MACHINERY_SERVED)));
101	    expect(state).toEqual({
102	      hasCompletedCycle: true,
103	      mode: "simple",
104	      phase: "served",
105	    });
106	  });
107	
108	  test("fetching without expiring first changes nothing", () => {
109	    expect(refetch(MACHINERY_SERVED)).toBe(MACHINERY_SERVED);
110	    expect(refetch(INITIAL_REBAKE_STATE)).toBe(INITIAL_REBAKE_STATE);
111	  });
112	
113	  test("fetching twice changes nothing the second time", () => {
114	    const once = refetch(expire(MACHINERY_SERVED));
115	    expect(refetch(once, "ffffff")).toBe(once);
116	  });
117	
118	  test("re-baking again clears the old comparison, which no longer has a subject", () => {
119	    const state = expire(refetch(expire(MACHINERY_SERVED)), LATER);
120	    expect(state).toEqual({
121	      expiredAt: LATER,
122	      hasCompletedCycle: true,
123	      mode: "machinery",
124	      phase: "expired",
125	    });
126	    expect(canFetch(state)).toBe(true);
127	  });
128	
129	  test("the simple view ignores the machinery's actions", () => {
130	    // A machinery press resolving after the switch flipped off must not strand
131	    // the simple view in a phase it cannot display. The panel disables the
132	    // switch while a press is in flight, so this is the belt to that brace.
133	    expect(expire(INITIAL_REBAKE_STATE)).toBe(INITIAL_REBAKE_STATE);
134	    expect(fuse(MACHINERY_SERVED)).toBe(MACHINERY_SERVED);
135	  });
136	});

