async (page) => {
  await page.goto('http://localhost:3001/', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.locator('#demo-02').scrollIntoViewIfNeeded({ timeout: 30000 });
  await page.waitForTimeout(800);
  // press re-bake to mint a fresh 6-char bake, then compare hash text vs swatch color
  await page.getByRole('button', { name: 'Re-bake this page' }).click();
  await page.waitForTimeout(4000);
  const check = await page.evaluate(() => {
    const stamp = document.querySelector('#demo-02 figure p.font-display');
    const hashText = stamp?.textContent?.match(/#([0-9a-f]+)/)?.[1] ?? null;
    const swatch = stamp?.querySelector('span[aria-hidden]');
    const bg = swatch ? getComputedStyle(swatch).backgroundColor : null;
    return { hashText, hashLength: hashText?.length, swatchBg: bg };
  });
  await page.locator('#demo-02 figure').screenshot({ path: './align-check.png' });
  return check;
}

